# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require_relative "../spec_helper"

RSpec.describe TimekeepingRules::EntryDecision do
  describe ".target_user" do
    # "An employee cannot create or edit a colleague's entry through user_id; an owner or admin can for a same-company user"
    it "coerces a string user_id before the shared target-user rule" do
      decide = lambda do |role, requested|
        described_class.target_user(acting_user_id: 1, role:, requested_user_id: requested, company_user_ids: [1, 7])
      end

      expect(decide.call("employee", "7")).to eq(:forbidden)
      expect(decide.call("employee", 7)).to eq(:forbidden)
      expect(decide.call("owner", "7")).to eq(:requested)
      expect(decide.call("admin", 7)).to eq(:requested)
      expect(decide.call("admin", "99")).to eq(:not_found)
      expect(decide.call("admin", 99)).to eq(:not_found)
      # A value that is not an id never names the acting user or user 0.
      expect(decide.call("admin", "7a")).to eq(:not_found)
      expect(decide.call("admin", "7; drop")).to eq(:not_found)
      expect(decide.call("employee", "")).to eq(:forbidden)
      expect(decide.call("employee", nil)).to eq(:acting)
      expect(defined?(Rails)).to be_nil
    end
  end

  describe ".version" do
    it "never reads a non-numeric If-Match as version 0" do
      expect(described_class.version(if_match: "abc", current_version: 0)).to eq(:version_conflict)
    end

    it "accepts a matching numeric If-Match and a missing one" do
      expect(described_class.version(if_match: "3", current_version: 3)).to eq(:ok)
      expect(described_class.version(if_match: nil, current_version: 3)).to eq(:ok)
      expect(described_class.version(if_match: "2", current_version: 3)).to eq(:version_conflict)
    end
  end
end
